'use client';
import { useState, useEffect, useRef, useCallback } from 'react';
import { ArrowUpRight, ArrowRight, BookOpen, LayoutDashboard, RotateCcw, Target, FileText, Newspaper, BarChart3, Sparkles, Settings, ShieldCheck, Search, Check, Plus, X, ChevronRight, Menu, Clock3, Cloud, CloudOff, LogOut, CheckCircle2, LockKeyhole, GraduationCap, Layers3, Timer, Send, Download, AlertCircle, Mail, UserRound, Flame, CircleHelp, CalendarDays } from 'lucide-react';
import { topics, subjects, lesson, rightsQuestions, gmaQuestions } from '../lib/content.js';
import type { StudyEvent } from '../lib/event-validation';
type User={id:string;name:string;email:string}|null;
type Member={userId:string;email:string;name:string;status:string;role?:string;createdAt:string};
