 const initialTasks=plan?[{...starterTasks[0],topic:plannedTopic.id,label:'Understand '+plannedTopic.title},starterTasks[1],{...starterTasks[2],topic:scienceTopic.id,label:scienceTopic.title},starterTasks[3]]:starterTasks;
 const completed=new Set(events.filter(e=>e.type==='complete').map(e=>String(e.data.topic)));
