 const questions=tab==='gma'?gmaQuestions:rightsQuestions;
 useEffect(()=>{if(!quizStarted||submitted)return;const end=Date.now()+360*1000;const timer=setInterval(()=>{const remaining=Math.max(0,Math.ceil((end-Date.now())/1000));setSeconds(remaining);if(remaining===0)setSubmitted(true);},1000);return()=>clearInterval(timer);},[quizStarted,submitted]);
 const correct=questions.filter((q,i)=>answers[i]===q.answer).length,wrong=Object.entries(answers).filter(([i,a])=>a!==questions[Number(i)]?.answer).length,score=correct-wrong/3;
 const finishQuiz=()=>{setSubmitted(true);if(!quizSaved&&record('practice',{score,correct,wrong,total:questions.length,attempted:Object.keys(answers).length,seconds:360-seconds,mode:tab})){setQuizSaved(true);notify('Result saved. Your score includes the negative marking penalty.');}};
 useEffect(()=>{if(quizStarted&&seconds===0&&!quizSaved&&activeRef.current){const e={id:crypto.randomUUID(),at:new Date().toISOString(),type:'practice',data:{score,correct,wrong,total:questions.length,attempted:Object.keys(answers).length,seconds:360,mode:tab}};queue.current.push(e);all.current=mergeEvents(all.current,[e]);setEvents(all.current);persist();setQuizSaved(true);setTimeout(()=>void pullRef.current(),1500);}},[quizStarted,seconds,quizSaved,score,correct,wrong,questions.length,answers,tab,persist]);
 const mutation=async(action:string,extra:Record<string,unknown>={})=>{setBusy(true);try{const res=await fetch('/api/workspace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,...extra})});const result=await res.json() as {error?:string};if(!res.ok)throw new Error(result.error);await pull();notify(action==='claim-owner'?'Your super admin workspace is ready.':'Access updated.');}catch(e){notify(e instanceof Error?e.message:'Please try again.');}finally{setBusy(false);}};
